import base64
import subprocess
import shutil
import sys
import zlib
from pathlib import Path


base = Path(__file__).resolve().parent
main = base / "app" / "main.py"
texto_actual = main.read_text(
    encoding="utf-8-sig"
).replace("\r\n", "\n")

if 'VERSION = "0.15.1"' not in texto_actual:
    raise RuntimeError(
        "Esta actualización necesita Ne-notoka "
        "HelioRegla 0.15.1"
    )

respaldo = base / "app" / "main.py.bak_0151"

if not respaldo.exists():
    shutil.copy2(main, respaldo)

archivos = {'CHANGELOG.md': '',
 'app/calibracion.py': '',
 'app/comparaciones.py': '',
 'app/filamentos.py': '',
 'app/i18n.py': '',
 'app/main.py': '',
 'app/mediciones.py': '',
 'app/proyectos.py': '',
 'crear_acceso_directo.py': '',
 'docs/ATAJOS.md': '',
 'docs/GUIA_DE_USO.md': ''}

for nombre, paquete in archivos.items():
    ruta = base / nombre
    ruta.parent.mkdir(parents=True, exist_ok=True)
    contenido_archivo = zlib.decompress(
        base64.b64decode(paquete)
    )
    ruta.write_bytes(contenido_archivo)

if sys.platform == "win32":
    try:
        subprocess.run(
            [
                sys.executable,
                str(base / "crear_acceso_directo.py"),
            ],
            check=True,
        )
    except Exception as error:
        print(
            "La aplicación se actualizó, pero el acceso directo "
            f"no pudo crearse: {error}"
        )

print("Actualización 0.16.0 instalada correctamente")
print(f"Respaldo conservado en: {respaldo}")
